//! Differential test of the legacy 0.4 mode against the published starfix 0.4.0 crate.
//!
//! `tests/common/legacy_corpus.rs` hashes ~62,500 inputs (the format-1 golden inputs, every
//! nested column type of the collision search with ~60 small tables, every leaf type in five
//! positions with nulls, slices at many offsets and batch splits) and folds every outcome —
//! the hash or "panicked" — into one digest per group. The published crate's digests are
//! committed in `tests/golden/legacy_v0_4_reference_digests.json` (generated by
//! `tools/legacy_v0_4_reference`; the two crates cannot be linked into one test binary because
//! both export the same uniffi symbols). `starfix::legacy::v0_4` must reproduce every digest.

#[path = "common/leaf_types.rs"]
mod leaf_types;
#[path = "common/legacy_corpus.rs"]
mod legacy_corpus;
#[path = "common/nested_types.rs"]
mod nested_types;

#[cfg(test)]
mod tests {
    #![expect(clippy::unwrap_used, reason = "Okay in test")]

    use std::fs;
    use std::path::Path;

    use arrow::array::{Array, RecordBatch};
    use arrow_schema::{Schema, SchemaRef};
    use starfix::legacy::v0_4::{ArrowDigester, HasherConfig};

    use crate::legacy_corpus::{group_digests, Api};

    fn schema(s: &Schema, include_metadata: bool) -> Vec<u8> {
        ArrowDigester::hash_schema(s, HasherConfig { include_metadata })
    }

    fn batch(b: &RecordBatch, include_metadata: bool) -> Vec<u8> {
        ArrowDigester::hash_record_batch(b, HasherConfig { include_metadata })
    }

    fn stream(s: &SchemaRef, batches: &[RecordBatch], include_metadata: bool) -> Vec<u8> {
        let mut d = ArrowDigester::new(s, HasherConfig { include_metadata });
        for b in batches {
            d.update(b);
        }
        d.finalize()
    }

    fn array(a: &dyn Array) -> Vec<u8> {
        ArrowDigester::hash_array(a)
    }

    #[test]
    fn legacy_v0_4_matches_the_published_0_4_0_crate() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"));
        let reference: serde_json::Value = serde_json::from_str(
            &fs::read_to_string(root.join("tests/golden/legacy_v0_4_reference_digests.json"))
                .unwrap(),
        )
        .unwrap();
        let expected = reference
            .get("groups")
            .and_then(serde_json::Value::as_array)
            .unwrap();
        let api = Api {
            schema,
            batch,
            stream,
            array,
        };
        let actual = group_digests(&api, root);
        assert_eq!(actual.len(), expected.len());
        for ((name, cases, digest), want) in actual.iter().zip(expected) {
            let field = |key: &str| want.get(key).unwrap();
            assert_eq!(field("name").as_str().unwrap(), *name);
            assert_eq!(
                field("cases").as_u64().unwrap(),
                *cases as u64,
                "{name}: case count"
            );
            assert_eq!(
                field("digest").as_str().unwrap(),
                digest,
                "{name}: starfix::legacy::v0_4 differs from the published starfix 0.4.0"
            );
        }
    }
}
